#include <stdio.h>
#include <string.h>

int str_index(const char *t, char c) {
  int i = 0;
  for (; t[i] != '\0'; i++) {
    if (t[i] == c)
      return i;
  }
  return -1;
}

int main() {
  char text[] = "Hello, world!";
  int index = str_index(text, 'o');
  if (index != -1) {
    printf("Character 'o' found at index: %d\n", index);
  } else {
    printf("Character 'o' not found.\n");
  }
  return 0;
}
